  const universeView=()=>{const i=universe.identity;$("#workspaceView").innerHTML=`<section class="identity-page"><div class="identity-art">${img(i,'map')}</div><div class="identity-copy"><span class="edition">UNIVERSE IDENTITY</span><h1>${escapeHTML(i.name)}</h1><h3>${escapeHTML(i.genre||'Genre and era unwritten')}</h3><p>${escapeHTML(i.description)}</p><div class="identity-totals">${stat(universe.characters.length,'CHARACTERS')}${stat(universe.locations.length+universe.maps.length,'PLACES')}</div><button class="primary-button" data-action="edit-universe">EDIT UNIVERSE IDENTITY</button></div></section>`};
