  $("#entityForm").addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target),type=d.get('type'),imageFile=e.target.elements.imageFile.files[0];if(type==='universe'){const before={...universe.identity};universe.identity={...universe.identity,name:d.get('name').trim(),genre:d.get('subtitle').trim(),meta:d.get('meta').trim(),origin:d.get('origin').trim(),image:d.get('image').trim(),description:d.get('description').trim()};if(imageFile){try{universe.identity.image=await uploadImage(imageFile,'universe','identity');universe.identity.imageResolved=await resolveAsset(universe.identity.image)}catch(error){toast(error.message);universe.identity=before;return}}recordSeasonActivity('universe_updated',universe.identity);$("#entityModal").hidden=true;shell();navigate('universe');persist('UNIVERSE IDENTITY UPDATED');return}const list=universe[pluralFor(type)],id=d.get('id')||`${type[0]}${Date.now()}`,old=list.find(x=>x.id===id),season=activeSeason(),previousLevel=validSeasonLevel(old?.seasonLevel),item={...old,id,name:d.get('name').trim(),subtitle:d.get('subtitle').trim(),meta:d.get('meta').trim(),origin:d.get('origin').trim(),image:d.get('image').trim()||old?.image||'',gallery:d.get('gallery').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8),description:d.get('description').trim(),...(type==='character'&&season?.status==='active'?{seasonLevel:Number(season.number)}:{})};if(imageFile){try{item.image=await uploadImage(imageFile,pluralFor(type),id);item.imageResolved=await resolveAsset(item.image)}catch(error){toast(error.message);return}}const galleryFiles=[...e.target.elements.galleryFiles.files].slice(0,Math.max(0,8-item.gallery.length));for(let n=0;n<galleryFiles.length;n++){try{item.gallery.push(await uploadImage(galleryFiles[n],'character-gallery',`${id}-${Date.now()}-${n}`))}catch(error){toast(error.message);return}}if(type==='character')item.galleryResolved=await Promise.all(item.gallery.map(resolveAsset));old?Object.assign(old,item):list.unshift(item);recordSeasonActivity(`${type}_${old?'updated':'created'}`,item,type==='character'&&season?`${item.name.toUpperCase()} ADVANCED TO SEASON LEVEL ${season.number}`:'');if(type==='character'&&validSeasonLevel(item.seasonLevel)!==previousLevel)seasonAdvancements.set(id,{from:previousLevel,to:validSeasonLevel(item.seasonLevel)});$("#entityModal").hidden=true;navigate(type==='character'?'characters':'locations',[type,id]);const saved=await persist(old?'ENTRY UPDATED':'NEW ENTRY DISCOVERED');if(saved&&type==='character')await updateSeasonMemory();else if(!saved)toast('UNSAVED CHANGES · BRIDGE RETRY REQUIRED')});
  $("#seasonForm").addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target),url=d.get('trailerUrl').trim();if(!streamableMedia(url)){toast('PASTE A VALID STREAMABLE EMBED OR CDN LINK');return}const id=`s${Date.now()}`,cover=e.target.elements.cover.files[0],season={id,number:Number(d.get('number')),name:d.get('name').trim(),theme:d.get('theme').trim(),description:d.get('description').trim(),coverImage:'',trailer:{type:'external',url},startDate:new Date().toISOString(),endDate:null,status:'active',activities:[],statistics:emptySeasonStats()};if(cover){try{season.coverImage=await uploadImage(cover,'seasons',id);season.coverResolved=await resolveAsset(season.coverImage)}catch(error){toast(error.message);return}}universe.seasons.push(season);universe.activeSeasonId=id;viewedSeasonId=null;recordSeasonActivity('season_started',season,'A new creative era opens.');$("#seasonModal").hidden=true;await persist('NEW SEASON BEGUN');shell();navigate('seasons')});
  $("#trailerSettingsForm").addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target),season=universe.seasons.find(item=>item.id===d.get('seasonId')),url=d.get('trailerUrl').trim();if(!season)return;if(!streamableMedia(url)){toast('PASTE A VALID STREAMABLE EMBED OR CDN LINK');return}season.trailer={type:'external',url};recordSeasonActivity('season_media',season,'The season trailer URL was updated.');$("#trailerSettingsModal").hidden=true;await persist('SEASON VIDEO URL UPDATED');currentPage==='home'?homeView():seasonsView()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$("#entityModal").hidden=true;$("#artLightbox").hidden=true;$("#trailerSettingsModal").hidden=true;$('.trailer-theater')?.remove();document.body.classList.remove('theater-open')}});
  (async()=>{addons=await desktop?.addonState()||addons;addons.audiobooks={...(addons.audiobooks||{}),installed:true};const saved=await loadSavedCredentials();if(saved){$("#owner").value=saved.owner;$("#repo").value=saved.repo;$("#token").value=saved.token;$("#remember").checked=true;$("#forgetButton").hidden=false}})();
